roofs"]={{["atomIDs"]={"6564:description:1-58","6564:description:63-121","6564:description:123-239","6564:description:244-313","6564:description:315-422","6564:description:424-455","6564:objective:1-51"},["minimumStage"]=2,["questID"]=6564,["sourceHash"]="6bdff20251c1e49e6d0b8e4597eb7f558135b95c6db0bb7536527070d9cb9ea0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-twilight-s-hammer",["kind"]="faction",["newSubject"]=false,["related"]={"blackfathom-deeps"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="A recovered note described the use of crystals containing water-elemental spirits to strengthen aquamancers’ summonings and appease Aku’mai.",["title"]="Twilight’s Hammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5761:description:1-151","5761:description:153-339","5761:description:344-443","5761:description:448-509","5761:objective:1-112"},["minimumStage"]=2,["questID"]=5761,["sourceHash"]="202ea01277acadb8cdd77f112c744431d088b6e1124adb3c39f503b5c641d898"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-searing-blade",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-instance-ragefire-chasm"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Searing Blade made its home in Ragefire Chasm beneath Orgrimmar, according to Neeru Fireblade’s public charge against the cult.",["title"]="Searing Blade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5761:description:1-151","5761:description:153-339","5761:description:344-443","5761:description:448-509","5761:objective:1-112"},["minimumStage"]=2,["questID"]=5761,["sourceHash"]="202ea01277acadb8cdd77f112c744431d08