description:37-86","9033:description:88-127","9033:description:132-170","9033:description:172-239","9033:description:244-264","9033:description:266-287","9033:description:289-439","9033:description:444-492","9033:objective:1-188"},["minimumStage"]=2,["questID"]=9033,["sourceHash"]="942bce3ea220243682961b1964722cf3822271863c84ee09ec4a41eea5c7abe9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-argent-dawn",["kind"]="faction",["newSubject"]=true,["related"]={"naxxramas"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Argent Dawn sought resistance to Kel’Thuzad’s renewed Scourge preparations, judging volunteers through action against the forces inside Naxxramas.",["title"]="Argent Dawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9033:description:1-32","9033:description:37-86","9033:description:88-127","9033:description:132-170","9033:description:172-239","9033:description:244-264","9033:description:266-287","9033:description:289-439","9033:description:444-492","9033:objective:1-188"},["minimumStage"]=2,["questID"]=9033,["sourceHash"]="942bce3ea220243682961b1964722cf3822271863c84ee09ec4a41eea5c7abe9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-argent-dawn",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="At Light’s Hope, Eligor Dawnbringer offered the services of the Dawn and Crusade to those who demonstrated their commitment against the necropolis.",["title"]="Argent Dawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9153:description:1-86","9153:description:88-206","9153:description:211-269","9153:descripti