files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Hydraxis treated strikes against the fire captains of Molten Core as a costly but valuable advance in the Waterlords’ war.",["title"]="Hydraxian Waterlords"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6805:description:1-79","6805:description:82-154","6805:description:159-288","6805:description:291-422","6805:description:427-503","6805:objective:1-89"},["minimumStage"]=2,["questID"]=6805,["sourceHash"]="0c6aa9669ffecf500295d3c2ffece35d2d20cc1b3f621ebee0d80f6082781052"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-hydraxian-waterlords",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Hydraxis wanted the air and earth servants’ efforts at the Crystal Vale disrupted, while admitting he did not know why they guarded their objects of power.",["title"]="Hydraxian Waterlords"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7461:description:1-22","7461:description:24-57","7461:description:62-94","7461:description:96-142","7461:description:144-213","7461:description:215-252","7461:description:254-313","7461:description:315-363","7461:objective:1-92","7461:objective:94-188","7461:objective:193-277","7461:objective:279-328","7461:objective:333-414"},["minimumStage"]=2,["questID"]=7461,["sourceHash"]="a053e1177887017ca1d0fc9cbe432b26a158fe07e25dba849ca4b87d2b3466ee"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="shendralar",["kind"]="faction",["newSubject"]=false,["related"]={"dire-maul"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Shen’dralar 