ethod"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"871:description:1-38","871:description:40-92","871:description:97-197","871:description:199-325","871:description:330-368","871:description:370-455","871:description:457-485","871:objective:1-119"},["minimumStage"]=2,["questID"]=871,["sourceHash"]="eb0453c9c873eaa31154495b7c4c5e8fa055cea511c0bb5b9335722d24e420f2"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-razormane",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Thork pointed toward Razormane dens northeast of the Crossroads, recognizable by the great thorny growths rising around them.",["title"]="Razormane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"850:description:1-47","850:description:50-128","850:description:131-216","850:description:219-232","850:description:237-307","850:description:312-347","850:description:350-396","850:description:401-430","850:objective:1-64"},["minimumStage"]=2,["questID"]=850,["sourceHash"]="ce969c8cc13097c1b1305cb961a8528aa18603527995cec7c54693f04cb450af"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-kolkar",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="New leaders were rallying the Barrens’ formerly disorganized Kolkar into a threat to tauren and Horde holdings, in Regthar Deathgate’s assessment.",["title"]="Kolkar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"850:description:1-47","850:description:50-128","850:description:131-216","850:description:219-2