t"]="A Deadwood ritual totem was plain in construction but carried a palpable despair, a tangible sign of the corruption afflicting the tribe.",["title"]="Deadwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2995:description:1-88","2995:description:90-276","2995:description:278-349","2995:description:354-415","2995:description:420-450","2995:description:453-499","2995:description:501-510","2995:objective:1-136"},["minimumStage"]=2,["questID"]=2995,["sourceHash"]="19e5562cdd68fcc7d53ede0c575c05cf8781aed8770f648f9bdd9a54e7b4ac9f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-highvale",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Highvale elves used Quel’Danil Lodge as a center of communication, with ambassadors forging relations and sharing knowledge about the Witherbark.",["title"]="Highvale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2995:description:1-88","2995:description:90-276","2995:description:278-349","2995:description:354-415","2995:description:420-450","2995:description:453-499","2995:description:501-510","2995:objective:1-136"},["minimumStage"]=2,["questID"]=2995,["sourceHash"]="19e5562cdd68fcc7d53ede0c575c05cf8781aed8770f648f9bdd9a54e7b4ac9f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-highvale",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Oran Snakewrithe sought to undermine Highvale alliances by burning the lodge’s records and correspondence.",["title"]="Highvale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-vilebranch",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Jintha’Alor was the Vilebranch capital in the southern Hinterlands, with prisoners held at the city’s heights.",["title"]="Vilebranch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7850:description:1-48","7850:description:50-117","7850:description:122-188","7850:description:190-310","7850:description:315-435","7850:objective:1-122","7850:objective:124-176"},["minimumStage"]=2,["questID"]=7850,["sourceHash"]="0ee4b4a6f30f217e1c5ba716e534cdd32b9399aee3afc58ae87236a8737aa84b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-vilebranch",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Torntusk attributed the tribe’s unnatural ferocity and madness to Priestess Hexx and vessels of tainted blood scattered through Jintha’Alor.",["title"]="Vilebranch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-vilebranch",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="A midnight Vilebranch raid took Elder Torntusk from Revantusk. Reports that Hexx planned to sacrifice him to Hakkar drove the rescue appeal.",["title"]="Vilebranch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3823:description:1-55","3823:description:60-89","3823:description:94-167","3823:description:169-295","3823:description:300-319","3823:description:321-379","3823:description:384-437","3823:description:442-464","3823:objective:1-116"},["minimumStage"]=2,["questID"]=3823,["sourceHash"]="fcb7476f123532f38a3590f57cb3f6569cc7ebf33471f8fc526f5f058337b104"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-firegut",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Firegut ogres allied with Blackrock orcs, guarding Dreadmaul Rock’s mineral resources and maintaining supply routes.",["title"]="Firegut"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3824:description:1-27","3824:description:29-61","3824:description:66-105","3824:description:107-229","3824:description:234-357","3824:description:362-391","3824:description:393-432","3824:description:434-467","3824:description:472-486","3824:objective:1-55","3824:objective:57-146"},["minimumStage"]=2,["questID"]=3824,["sourceHash"]="eac2aab1d498400c32ab604b5b46238d21eb0a75457b2dc2327227bc3a233038"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-firegut",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Oralius’s campaign targeted the brute lord Gor’tesh, whose headquarters lay in a Blackrock building west of Dreadmaul Rock.",["title"]="Firegut"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-dragonmaw",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Dragonmaw expansion from the Wetlands into Dun Algaz threatened to cut Loch Modan off from Menethil Harbor.",["title"]="Dragonmaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"20:description:1-100","20:description:103-204","20:description:209-242","20:description:245-321","20:description:326-447","20:description:450-503","20:objective:1-56"},["minimumStage"]=2,["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-blackrock-clan",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Marris reported Blackrock orcs arriving from the Burning Steppes and seizing Stonewatch Keep as a base for raids against Lakeshire.",["title"]="Blackrock Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"19:description:1-89","19:description:92-165","19:description:168-199","19:objective:1-54"},["minimumStage"]=2,["questID"]=19,["sourceHash"]="ce86264a823f491954fef6ceb0e5042afc9a26497146de83c3a6a70d9795f0af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-blackrock-clan",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Tharil’zun led the Blackrock outrunners whose ambushes, together with renegades, threatened the approaches between Lakeshire and Stonewatch.",["title"]="Blackrock Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"56:description:1-89","56:description:92-194","56:description:199-248","56:description:250-392","56:description:395-429","56:objective:1-99"},["minimumStage"]=2,["questID"]=56,["sourceHash"]="59f75d213ea4a884962af47d85c5d0152e2722dfb377a08546d1c7ee5d9109a6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-the-night-watch",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Night Watch defended Darkshire under Althea Ebonlocke after Stormwind withdrew its commissioned guards from Duskwood.",["title"]="The Night Watch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"58:description:1-42","58:description:45-89","58:description:92-142","58:description:145-246","58:objective:1-114"},["minimumStage"]=2,["questID"]=58,["sourceHash"]="6a682c0e4e29b230aaf08a2a787f92a51894d13eb8617a22c3c92c35b342a5fa"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-the-night-watch",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Too few Watchers remained to secure Darkshire while undead occupied Raven Hill’s eastern mausoleum, forcing appeals for outside help.",["title"]="The Night Watch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"685:description:1-100","685:description:103-231","685:description:236-348","685:description:353-403","685:objective:1-75"},["minimumStage"]=2,["questID"]=685,["sourceHash"]="dcfcec2e568c6fb177a2219c67ed183fac2719d6c2851a9b4ad9609e93488256"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-stromgarde-militia",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The militia sought bounties on Falconcrest and Otto to disrupt the Syndicate’s Arathi operations and avenge defenders killed by the bodyguard.",["title"]="Stromgarde Militia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"685:description:1-100","685:description:103-231","685:description:236-348","685:description:353-403","685:objective:1-75"},["minimumStage"]=2,["questID"]=685,["sourceHash"]="dcfcec2e568c6fb177a2219c67ed183fac2719d6c2851a9b4ad9609e93488256"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-the-syndicate",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Lord Falconcrest headed the Syndicate’s Arathi efforts, supported by his bodyguard Otto, according to the militia’s bounty notice.",["title"]="The Syndicate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"684:description:1-104","684:description:107-180","684:description:185-227","684:description:232-320","684:description:323-366","684:objective:1-53"},["minimumStage"]=2,["questID"]=684,["sourceHash"]="0f13e19f89f7d0863f6a3b5e69efdbec2784164f4c8bbe0473f6a30208bab7c1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-the-syndicate",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Marez Cowl was a senior Syndicate adviser and operative in its territory within Stromgarde, warned against as a warlock dealing with demons.",["title"]="The Syndicate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["minimumStage"]=2,["questID"]=5863,["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-dunemaul",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="A nomadic Dunemaul band recently established a large desert compound south of Gadgetzan, while smaller groups ranged into Tanaris’s old troll ruins.",["title"]="Dunemaul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["minimumStage"]=2,["questID"]=5863,["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-dunemaul",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Gor’marok the Ravager led the compound’s ogres. Andi Lynn believed removing his leadership would weaken the gathering force.",["title"]="Dunemaul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8154:description:1-60","8154:description:63-163","8154:description:168-205","8154:description:208-270","8154:description:273-348","8154:description:353-385","8154:description:388-503","8154:objective:1-114"},["minimumStage"]=2,["questID"]=8154,["sourceHash"]="0904fe3d1a5042cc6f14e8423e0355ac25ebab74bfbe1a3b4a8b9adbfd81ff9b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-league-of-arathor",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The League sought Arathi Basin's metals, weapons, food and timber because soldiers could not fight effectively without reliable equipment and provisions.",["title"]="League of Arathor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8105:description:1-72","8105:description:75-197","8105:description:200-270","8105:description:275-375","8105:description:378-431","8105:description:436-492","8105:objective:1-118"},["minimumStage"]=2,["questID"]=8105,["sourceHash"]="d4d02a5095cdbf3b61511d7c059ff96d1970a9032438d5e64549ef323ee4686a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-league-of-arathor",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Oslight's offensive targeted enemy banners at the farm, mine, lumber mill and blacksmith, tying territorial assaults to the working sites supplying his forces.",["title"]="League of Arathor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8123:description:1-75","8123:description:78-203","8123:description:206-282","8123:description:287-306","8123:description:309-389","8123:description:392-492","8123:objective:1-114"},["minimumStage"]=2,["questID"]=8123,["sourceHash"]="b22f5703a54e0ba16121bdcbd0101a9d4a943292382fffb495ab1c6e47be6531"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-the-defilers",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Mortis regarded the League's expansion from Refuge Pointe as a threat to be stopped by taking its supplies. The same resources would then sustain the Defilers' own campaign.",["title"]="The Defilers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8122:description:1-124","8122:description:127-188","8122:description:191-249","8122:description:252-313","8122:description:316-431","8122:description:436-487","8122:objective:1-97"},["minimumStage"]=2,["questID"]=8122,["sourceHash"]="106a33a83e3e375a3dbab3f0a9fe0691f83a5ca1f7886b453b4f6abb947f8b36"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-the-defilers",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Dwire's scouts reported a weakening in the League's resolve. He wanted the opening exploited through simultaneous control of every strategic base.",["title"]="The Defilers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81","8984:completion:1-29","8984:completion:31-56","8984:completion:58-70","8984:completion:75-223","8984:completion:228-261","8984:completion:263-324","8984:completion:329-355","8984:completion:357-399","8984:completion:401-441","8984:completion:443-497"},["minimumStage"]=4,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="shadow-council",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Staffron confessed a plan to weaken Alliance and Horde alike through enchanted fragrances, leaving distracted warriors unable to oppose the Council's rise.",["title"]="The Shadow Council"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["minimumStage"]=2,["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="shadow-council",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Banehollow's quarrel with Hel'nurath reached into the Council's Jaedenar holdings when he accused Ulathek of serving the rival on Xoroth.",["title"]="The Shadow Council"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1098:description:1-108","1098:description:111-242","1098:description:247-271","1098:description:274-355","1098:description:358-405","1098:description:410-460","1098:description:463-474","1098:objective:1-55"},["minimumStage"]=2,["questID"]=1098,["sourceHash"]="311353a24daa35caf0d471c83674e04c4c6fc994ca789dac1f4afc100b06afbd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-deathstalkers",["kind"]="faction",["newSubject"]=true,["related"]={"shadowfang-keep"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Forsaken scouts sought intelligence inside Shadowfang Keep so Hadrec could prepare an assault on Arugal. The disappearance of Adamant and Vincent left that operation without its needed report.",["title"]="Deathstalkers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4983:description:1-33","4983:description:35-93","4983:description:95-143","4983:description:148-161","4983:description:163-195","4983:description:197-251","4983:objective:1-74","4983:completion:1-92","4983:completion:94-175","4983:completion:180-230"},["minimumStage"]=4,["questID"]=4983,["sourceHash"]="675d7b2061b62d6f823b4d8e4ac62d4d1b0203fd3297d92d5f3ae3c5e5109bb4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-kargath-expeditionary-force",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Bijou's reconnaissance inside Blackrock Spire supplied information Lexlort considered strategically valuable against the orcs, despite his anger over her competing work for Kibler.",["title"]="Kargath Expeditionary Force"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4081:description:1-76","4081:description:81-167","4081:description:172-299","4081:description:301-376","4081:description:381-494","4081:objective:1-60","4081:objective:65-169","4081:objective:171-211"},["minimumStage"]=2,["questID"]=4081,["sourceHash"]="cbaa4ffbab226c28e3f7c3e0bfe48761e9c1133139ba44582f7c9cac1f94d95d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-kargath-expeditionary-force",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Goretooth's campaign against Angerforge's men was driven by the loss of the expedition's 109th division. Strikes against the Anvilrage front line began his intended retaliation.",["title"]="Kargath Expeditionary Force"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4082:description:1-76","4082:description:81-98","4082:description:100-223","4082:description:225-318","4082:description:320-363","4082:description:368-419","4082:objective:1-60","4082:objective:65-169","4082:objective:171-211"},["minimumStage"]=2,["questID"]=4082,["sourceHash"]="d41a84b88fc7b5b8e4a51b23f7317bb27a11978e58f739c8b3e9710f40086951"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-anvilrage",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Lexlort's reconnaissance placed Anvilrage medics, soldiers and officers in training behind a locked gate toward the center of Blackrock Depths.",["title"]="Anvilrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4081:description:1-76","4081:description:81-167","4081:description:172-299","4081:description:301-376","4081:description:381-494","4081:objective:1-60","4081:objective:65-169","4081:objective:171-211"},["minimumStage"]=2,["questID"]=4081,["sourceHash"]="cbaa4ffbab226c28e3f7c3e0bfe48761e9c1133139ba44582f7c9cac1f94d95d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-anvilrage",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Goretooth treated the Anvilrage forces as Angerforge's command, directing successive strikes against the general's front line and the troops deeper in the city.",["title"]="Anvilrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4724:description:1-92","4724:description:94-202","4724:description:207-267","4724:description:269-321","4724:description:323-369","4724:description:371-379","4724:description:381-431","4724:description:436-467","4724:description:469-486","4724:description:488-511","4724:objective:1-49"},["minimumStage"]=2,["questID"]=4724,["sourceHash"]="86f161373affd087bd190c4ac8c1515e067bf4a6bff8359a60ddee7e1f8cd5d4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-bloodaxe",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Halycon was the enormous den mother of the Bloodaxe worgs. Galamav described her and her mate as the source of the animals controlled by Blackrock's orcs.",["title"]="Bloodaxe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4742:description:1-59","4742:description:61-151","4742:description:153-271","4742:description:276-412","4742:description:414-448","4742:description:450-467","4742:objective:1-116","4742:objective:118-184","4742:objective:189-346"},["minimumStage"]=2,["questID"]=4742,["sourceHash"]="e00aca0dc61cb6fcdaa5961efe2a1e382b5dcdde41ea28581b695bf16961de20"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-smolderthorn",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Vaelan associated War Master Voone with the Smolderthorn command gemstone required for the Seal of Ascension.",["title"]="Smolderthorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4742:description:1-59","4742:description:61-151","4742:description:153-271","4742:description:276-412","4742:description:414-448","4742:description:450-467","4742:objective:1-116","4742:objective:118-184","4742:objective:189-346"},["minimumStage"]=2,["questID"]=4742,["sourceHash"]="e00aca0dc61cb6fcdaa5961efe2a1e382b5dcdde41ea28581b695bf16961de20"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-spirestone",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Highlord Omokk bore the Spirestone command gemstone sought for Vaelan's seal, linking the ogre leader to one of the artifact's three sockets.",["title"]="Spirestone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7581:description:1-78","7581:description:83-154","7581:description:156-235","7581:objective:1-117","7581:objective:119-171"},["minimumStage"]=2,["questID"]=7581,["sourceHash"]="bd91409d4e034fab77d88c649890d51c67592bc461f099d64ca35e944b0c7300"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-wildspawn",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Wildspawn satyr blood from Dire Maul's Warpwood Quarter could bond Daio's Hederine crystals and power his proposed Doomguard prison.",["title"]="Wildspawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7582:description:1-155","7582:description:157-218","7582:description:223-329","7582:description:334-399","7582:objective:1-127","7582:objective:129-197"},["minimumStage"]=2,["questID"]=7582,["sourceHash"]="eacad3eb0882af97ff16c8c7326dc24c03d3bdcde8d51e69ed628958a95efdb0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-hederine",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Daio described Hederine fel poison hardening with age into dense anti-magic crystals. He sought these Tears from the demons of Darkwhisper Gorge for his prison's walls.",["title"]="Hederine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7703:description:1-103","7703:description:106-233","7703:description:238-284","7703:description:287-356","7703:description:359-481","7703:description:484-499","7703:objective:1-82","7703:objective:87-239"},["minimumStage"]=2,["questID"]=7703,["sourceHash"]="30ec8c2fbcfbb917e18eb4504f998c6afcea32b48cda0902a86fd5d70162af28"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-gordok",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Kromcrush's traditions told of Tortheldrin stealing a gauntlet from a former Gordok king. Recovering it was supposed to identify the tribe's true ruler.",["title"]="Gordok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7703:description:1-103","7703:description:106-233","7703:description:238-284","7703:description:287-356","7703:description:359-481","7703:description:484-499","7703:objective:1-82","7703:objective:87-239","7703:completion:1-6","7703:completion:8-37","7703:completion:39-83","7703:completion:85-127","7703:completion:129-172","7703:completion:174-200","7703:completion:205-299","7703:completion:301-432","7703:completion:437-467","7703:completion:469-508"},["minimumStage"]=4,["questID"]=7703,["sourceHash"]="30ec8c2fbcfbb917e18eb4504f998c6afcea32b48cda0902a86fd5d70162af28"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-gordok",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Gordok captain was taught how to awaken the ancient magical mark on the lost gauntlet, preserving a practical rite alongside the legend of rightful rule.",["title"]="Gordok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7649:description:1-43","7649:objective:1-39"},["minimumStage"]=2,["questID"]=7649,["sourceHash"]="42a61b614ac5587f4229b6989546d5590e3b455edfb18430531c559c0f98ff31"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="shendralar",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Their Athenaeum's mark identified displaced books, whose return brought a recipe page from Lorekeeper Lydros as acknowledgment.",["title"]="The Shen’dralar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8870:description:1-31","8870:description:34-137","8870:description:140-254","8870:description:257-296","8870:objective:1-69","8870:objective:72-142"},["minimumStage"]=2,["questID"]=8870,["sourceHash"]="cbe0bee9d3d14dfdd11008eb7c28d417a905358aa4c4bac83f700e1eca17e7f5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-cenarion-circle",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Circle invited people throughout Azeroth to the Lunar Festival. City harbingers waited at blessed moonlight circles to explain participation in the celebration.",["title"]="Cenarion Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8980:description:1-19","8980:description:21-77","8980:description:79-136","8980:description:141-237","8980:description:239-327","8980:objective:1-59"},["minimumStage"]=2,["questID"]=8980,["sourceHash"]="b6f2b664a2018f9d6246b0b6e5e0ac4998eef6620e46f5d9de28a7b4572e3212"}},["questSourceProofsMode"]="ALL"},["field"]=