/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Baine described failed attempts to communicate with the gnolls and unrestrained killing of Mulgore’s wildlife as the reasons he sought armed opposition.",["title"]="Palemane tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"780:description:1-97","780:description:99-184","780:description:189-296","780:objective:1-120"},["minimumStage"]=2,["questID"]=780,["sourceHash"]="f67aaed6d666fa08f49d52d07a72aa998a622f44a8d1ce401c10cd2ade740406"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-bristleback-tribe",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-mulgore"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Bristlebacks trained malicious battleboars that encroached on Camp Narache’s hunting grounds.",["title"]="Bristleback tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"833:description:1-85","833:description:87-265","833:description:270-334","833:description:336-450","833:description:455-493","833:objective:1-78"},["minimumStage"]=2,["questID"]=833,["sourceHash"]="f9872148b2974728380e24dbd13a3b276a45dd07873d32c1700720381eb5751f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-bristleback-tribe",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Lorekeeper Raintotem accused Bristleback interlopers of ravaging Red Rocks, a burial ground reserved for honored tauren.",["title"]="Bristleback tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4763:description:1-68","4763:description:71-131","4763:description:134-236","4763:description:241-335","4763:description:338-479","4763:description:481-503","4763:objective:1-56","4763:objective:61-143","4763:objective:148-280","4763:objective:285-365"},["minimumStage"]=2,["questID"]=4763,["sourceHash"]="07ade58cf6d59605518f5a5cf692879f299efcf242d5f8677277fd1922572fdd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-blackwood-tribe",["kind"]="faction",["newSubject"]=true,["related"]={"darkshore"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Thundris identified a satyr talisman as a means of holding the Blackwood furbolgs under corrupt influence.",["title"]="Blackwood tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4763:description:1-68","4763:description:71-131","4763:description:134-236","4763:description:241-335","4763:description:338-479","4763:description:481-503","4763:objective:1-56","4763:objective:61-143","4763:objective:148-280","4763:objective:285-365"},["minimumStage"]=2,["questID"]=4763,["sourceHash"]="07ade58cf6d59605518f5a5cf692879f299efcf242d5f8677277fd1922572fdd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-blackwood-tribe",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="His proposed offering combined moonwell water with the tribe’s fruit, nuts and grain, seeking a temporary cleansing that would expose the satyr corruptor.",["title"]="Blackwood tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4763:description:1-68","4763:description:71-131","4763:descripti