/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Circle sought large quantities of Un’Goro’s magically potent soil for study, with Ghede gathering the samples for Hamuul.",["title"]="Cenarion Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1050:description:1-25","1050:description:27-95","1050:description:100-200","1050:description:205-314","1050:description:316-419","1050:description:424-497","1050:objective:1-104"},["minimumStage"]=2,["questID"]=1050,["sourceHash"]="d3f78f7ef80dc178781cfc97c641c8fe30e2ecfcddb7442957728ae281e24d1f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-explorers-league",["kind"]="faction",["newSubject"]=true,["related"]={"ironforge","scarlet-monastery"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Mae Paledust saw the recovery of Mythology of the Titans as a means to prepare for the future by understanding the past.",["title"]="Explorers’ League"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2238:description:1-61","2238:description:63-121","2238:description:126-158","2238:description:160-178","2238:description:180-197","2238:description:202-340","2238:description:345-428","2238:description:430-484","2238:description:486-496","2238:objective:1-34"},["minimumStage"]=2,["questID"]=2238,["sourceHash"]="7f85ccb4ebf99e8ac62050b3cc04baba8c449b128c47f10c209a814157f70b8a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-hidden-circle",["kind"]="faction",["newSubject"]=true,["related"]={"ironforge"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Circle wanted a clandestine share of the king’s quarry riches, with Hulfdan planning to take it without the monarch knowing.",["title"]="Hidden Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2238:description:1-61","2238:description:63-121","2238:description:126-158","2238:description:160-178","2238:description:180-197","2238:description:202-340","2238:description:345-428","2238:description:430-484","2238:description:486-496","2238:objective:1-34"},["minimumStage"]=2,["questID"]=2238,["sourceHash"]="7f85ccb4ebf99e8ac62050b3cc04baba8c449b128c47f10c209a814157f70b8a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-hidden-circle",["kind"]="faction",["newSubject"]=false,["related"]={"gnomeregan"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Onin MacHammar hid among the leper gnomes near Gnomeregan to gather the report Hulfdan needed for the operation.",["title"]="Hidden Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1437:description:1-20","1437:description:22-131","1437:description:133-234","1437:description:236-331","1437:description:336-416","1437:description:421-478","1437:objective:1-62"},["minimumStage"]=2,["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-house-malem",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="House Malem was a Darnassian merchant family whose missing nobles prompted Vahlarriel’s search.",["title"]="House Malem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1437:description:1-20","1437:description:22-131","1437:description:133-234","1437:description:236-331","1437:description:336-416","1437:description:421-478","1437:objective:1-62"},["minimumStage"]=2,["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-house-malem",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The family’s father feared for Tyranis and Dalinda after their journey through Stonetalon; the search began with their missing wagon.",["title"]="House Malem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1707:description:1-96","1707:description:99-105","1707:description:110-239","1707:description:242-305","1707:description:308-402","1707:description:405-466","1707:objective:1-76"},["minimumStage"]=2,["questID"]=1707,["sourceHash"]="628ae04a11e9f269ddb2ed1683e727c75a6385e521e1d58d56e89ac0f0c2d6f9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-gadgetzan-water-company",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-tanaris"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The company exchanged care packages for recovered water pouches as part of Gadgetzan’s effort to recover its supply.",["title"]="Gadgetzan Water Company"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1707:description:1-96","1707:description:99-105","1707:description:110-239","1707:description:242-305","1707:description:308-402","1707:description:405-466","1707:objective:1-76"},["minimumStage"]=2,["questID"]=1707,["sourceHash"]="628ae04a11e9f269ddb2ed1683e727c75a6385e521e1d58d56e89ac0f0c2d6f9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-gadgetzan-water-company",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Spigot Operator Luglunket said Wastewander nomads had stolen the company’s water and urged travelers to bring it back.",["title"]="Gadgetzan Water Company"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1886:description:1-104","1886:description:109-167","1886:description:172-213","1886:description:215-323","1886:description:325-382","1886:description:387-460","1886:description:462-495","1886:objective:1-89"},["minimumStage"]=2,["questID"]=1886,["sourceHash"]="efdc225b5c9229a83ecb971c81c1304b8a1bfebb145ab331393b1da940443ca1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-deathstalkers",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-undercity"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Mennet described the Deathstalkers as Varimathras’s elite guard and tested recruits through dangerous, deliberately undisclosed business.",["title"]="Deathstalkers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3821:description:1-145","3821:description:150-281","3821:description:283-301","3821:description:303-317","3821:description:322-386","3821:description:388-436","3821:objective:1-82"},["minimumStage"]=2,["questID"]=3821,["sourceHash"]="92f3223a6174f263a7521a60d3468d8d82f55b4d1c3d18a1a1cbbe49fe680877"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-firegut",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-burning-steppes"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Reports of strange Firegut rituals drew Sha’ni’s platoon into the Burning Steppes; weeks without news left her husband seeking an independent search.",["title"]="Firegut"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["minimumStage"]=2,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-druids-of-the-fang",["kind"]="faction",["newSubject"]=true,["related"]={"wailing-caverns"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Fang druids had belonged to a noble order that intended to heal the Barrens before its purpose turned toward corrupted dreams.",["title"]="Druids of the Fang"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["minimumStage"]=2,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-druids-of-the-fang",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Nara described their new purpose as remaking the Barrens to match their own twisted dreams, overturning the original effort to restore it.",["title"]="Druids of the Fang"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["minimumStage"]=2,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-druids-of-the-fang",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Four leaders within the Wailing Caverns each possessed a dream gem, which Nara wanted taken from them.",["title"]="Druids of the Fang"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61","91282:completion:1-46"},["minimumStage"]=4,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-tyr-s-watch",["kind"]="faction",["newSubject"]=true,["related"]={"bandarion-keep"},["sourceURL"]="https://warcraftforever.games/quests/91282",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Tyr’s Watch was the new order welcoming Tirisfal’s risen paladins into a community of shared faith.",["title"]="Tyr’s Watch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61"},["minimumStage"]=2,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-tyr-s-watch",["kind"]="faction",["newSubject"]=false,["related"]={"bandarion-keep"},["sourceURL"]="https://warcraftforever.games/quests/91282",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Its monastery occupied Bandarion Keep at Northface Rock, on the bluffs northwest of Solliden Farmstead.",["title"]="Tyr’s Watch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92595:description:1-195","92595:objective:1-83"},["minimumStage"]=2,["questID"]=92595,["sourceHash"]="47865ded0bab06eb5d9767e72362a3f2a8c98b200ffcfb39c98997d65e7b5ec6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-windshapers",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-zephras-isle"},["sourceURL"]="https://warcraftforever.games/quests/92595",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Those with skysight could help restore dialogue with the wind spirits, including gifted people who had never trained as shamans.",["title"]="Windshapers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92595:description:1-195","92595:objective:1-83","92595:completion:1-266"},["minimumStage"]=4,["questID"]=92595,["sourceHash"]="47865ded0bab06eb5d9767e72362a3f2a8c98b200ffcfb39c98997d65e7b5ec6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-windshapers",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://warcraftforever.games/quests/92595",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Illaya understood that responsibility as preserving the Shen’dorei’s home amid internal enemies and uncertainty about safety in Skywall.",["title"]="Windshapers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83","92514:completion:1-215"},["minimumStage"]=4,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-windshapers",["kind"]="faction",["newSubject"]=false,["related"]={"shendar-village"},["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Despite tension with the High Order, both groups kept civil relations in Shen’dar when faced with larger threats.",["title"]="Windshapers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83","92514:completion:1-215"},["minimumStage"]=4,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-high-order",["kind"]="faction",["newSubject"]=true,["related"]={"shendar-village"},["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Shen’dar’s constable valued the order’s willingness to keep its dispute with the Windshapers civil while the village faced more immediate dangers.",["title"]="High Order"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92551:description:1-245","92551:objective:1-64"},["minimumStage"]=2,["questID"]=92551,["sourceHash"]="ef9dfb838dc8627d74e00ac7f202ce3ce957769e2dcf7b788bcd7afb04652a08"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-al-aketh",["kind"]="faction",["newSubject"]=true,["related"]={"shendar-village","falaath-village"},["sourceURL"]="https://warcraftforever.games/quests/92551",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Danarii blamed the cult for months of caravan raids stealing food and windstones, despite its attempts to accuse ordinary bandits.",["title"]="Al’Aketh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"93165:description:1-197","93165:objective:1-57"},["minimumStage"]=2,["questID"]=93165,["sourceHash"]="575bb52ecf51516cc957f76234bf17702fbe0a3359398ec8e7c48d9bb11fcf11"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="faction-nightclaw-druids",["kind"]="faction",["newSubject"]=true,["related"]={"shadowgale-forest"},["sourceURL"]="https://warcraftforever.games/quests/93165",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Vayn sought repayment for tragedy suffered by the enclave, offering bounties against the cult and deeper knowledge only to helpers who earned trust.",["title"]="Nightclaw Druids"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96898:description:1-213","96898:objective:1-60"},["minimumStage"]=2,["questID"]=96898,["sourceHash"]="92ca3e7936276f99661ccbd0cf092febbfe923b0e510baf1a2e6515fcc1b0d97"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-argent-dawn",["kind"]="faction",["newSubject"]=false,["related"]={"naxxramas","atlas-place-tirisfal-glades"},["sourceURL"]="https://warcraftforever.games/quests/96898",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Hadric recalled losses shared with the Forsaken during Naxxramas’s assault, when its shattered necrotic focusing crystal scattered fragments across Tirisfal.",["title"]="Argent Dawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96899:description:1-190","96899:objective:1-60","96899:completion:1-214"},["minimumStage"]=4,["questID"]=96899,["sourceHash"]="84f15e2629f15d0b61293f6cec889ad58af187c0c56d45a6d36484386d5f949e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-argent-dawn",["kind"]="faction",["newSubject"]=false,["related"]={"bandarion-keep"},["sourceURL"]="https://warcraftforever.games/quests/96899",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Leonid remembered the order preparing battles from Bandarion’s fortress before withdrawing to the Plaguelands, and welcomed the paladins’ later stewardship.",["title"]="Argent Dawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8062:description:1-132","8062:description:135-251","8062:description:254-347","8062:description:352-421","8062:description:424-495","8062:objective:1-105","8062:objective:108-197","8062:objective:202-270"},["minimumStage"]=2,["questID"]=8062,["sourceHash"]="357f24c4be119177445485b40c69e2e638aa108e1ca7f6574128f70b75c44afe"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-zandalar-tribe",["kind"]="faction",["newSubject"]=false,["related"]={"zul-gurub"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="After the Gurubashi Empire’s fall, Zandalar’s predators helped sustain their people through skill in the hunt.",["title"]="Zandalar Tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8056:description:1-80","8056:description:83-199","8056:description:202-321","8056:description:326-420","8056:description:423-507","8056:objective:1-53","8056:objective:56-145","8056:objective:150-216"},["minimumStage"]=2,["questID"]=8056,["sourceHash"]="ce6dabf9cca7287812c059f9f903ecce5ce0cf269eae385618770cd11530797d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-zandalar-tribe",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The tribe revered its augurs’ divine sight through bones and leaves, distinguishing their divination from a witch doctor’s hexes.",["title"]="Zandalar Tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8059:description:1-101","8059:description:104-181","8059:description:184-318","8059:description:321-361","8059:description:366-457","8059:description:460-500","8059:objective:1-57","8059:objective:60-149","8059:objective:154-224"},["minimumStage"]=2,["questID"]=8059,["sourceHash"]="8f01143b1bcc04f7c449e30c5b89296b21b903c69cd8c97ab4689b210c12e231"}},["questSourceProofsMode"]="ALL"},["field"]="stakes",["id"]="faction-zandalar-tribe",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Demoniacs let a demon enter them through an ancient ritual, then sought to enslave its power from within rather than surrender to possession; few mastered the practice.",["title"]="Zandalar Tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8195:description:1-62","8195:description:65-178","8195:description:183-224","8195:description:227-312","8195:description:315-401","8195:description:404-497"},["minimumStage"]=2,["questID"]=8195,["sourceHash"]="4e91a719b416a207d6a782bbcafa85443d5258cc02108feea596373b7ea0445b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-zandalar-tribe",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Nine kinds of tribal coin circulated in Zul’Gurub. Vinchaxa exchanged sets for Honor Tokens usable with Rin’wosho, alongside the coins needed for certain battle gear.",["title"]="Zandalar Tribe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["minimumStage"]=2,["questID"]=505,["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-the-syndicate",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-alterac-mountains"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Syndicate was led by former nobles of the ruined kingdom of Alterac, who turned to theft and covert power after its fall.",["title"]="The Syndicate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["minimumStage"]=2,["questID"]=505,["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-the-syndicate",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Camps at Sofera’s Naze and Corahn’s Dagger gave the group footholds north and west of Horde-held Tarren Mill.",["title"]="The Syndicate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["minimumStage"]=2,["questID"]=505,["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-the-syndicate",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Southshore’s new magistrate strongly suspected Syndicate involvement in his predecessor’s assassination, though the killers had not been found.",["title"]="The Syndicate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8460:description:1-66","8460:description:68-170","8460:description:172-225","8460:description:230-268","8460:description:270-360","8460:description:362-449","8460:objective:1-116","8460:objective:119-197"},["minimumStage"]=2,["questID"]=8460,["sourceHash"]="4b7bcbbf6d7b0a20819c7ba6d7bc8bee5bc39a234227e42dbd7f44cfe6888af1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="faction-timbermaw",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-felwood"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Grazle blamed other peoples’ indiscriminate attacks on furbolgs for his tribe’s reluctance to trust outsiders who failed to distinguish friend from foe.",["title"]="Timbermaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8481:description:1-145","8481:description:150-238","8481:description:241-303","8481:description:306-358","8481:description:361-462","8481:description:464-499","8481:objective:1-111","8481:objective:114-204"},["minimumStage"]=2,["questID"]=8481,["sourceHash"]="a35930f6756c031fe4c0dc1f1ca7d1e0e21570ea24dc57b5d10c50895ff563ea"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-winterfall",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-winterspring"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Gorn believed a demon dominated the tribe and proposed confronting it at the high chief’s cave; its essence would begin a lengthy healing, not instantly undo the corruption.",["title"]="Winterfall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7841:description:1-76","7841:description:78-129","7841:description:134-146","7841:description:151-247","7841:description:249-336","7841:description:341-363","7841:objective:1-165","7841:objective:167-207","7841:objective:212-318"},["minimumStage"]=2,["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-highvale",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-the-hinterlands"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Highvale elves’ new dealings with the Wildhammer alarmed the Revantusk, who treated the alliance as a threat in the Hinterlands.",["title"]="Highvale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6961:description:1-36","6961:description:39-81","6961:description:84-184","6961:description:187-237","6961:description:242-318","6961:description:321-361","6961:description:364-442","6961:objective:1-98"},["minimumStage"]=2,["questID"]=6961,["sourceHash"]="f95823d900b483e1d1525458afb9bdfb02a0d828852d0f907c1bb690bcb0752c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-smokywood-pastures",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Smokywood Pastures sold seasonal treats promoted by the Copperpinch merchants as wholesome farm-to-table fare for Winter Veil gifts.",["title"]="Smokywood Pastures"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7042:description:1-9","7042:description:11-155","7042:description:160-339","7042:description:342-452","7042:description:457-498","7042:objective:1-111"},["minimumStage"]=2,["questID"]=7042,["sourceHash"]="79c4bb3ff70b7dc3b43430bb109493ab46082d1eef716273325dcf572566f1b0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-smokywood-pastures",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-alterac-mountains"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="A missing shipment threatened the season’s supply, and the company’s investigator also disappeared after following its trail into Alterac.",["title"]="Smokywood Pastures"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7841:description:1-76","7841:description:78-129","7841:description:134-146","7841:description:151-247","7841:description:249-336","7841:description:341-363","7841:objective:1-165","7841:objective:167-207","7841:objective:212-318"},["minimumStage"]=2,["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-wildhammer-clan",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-the-hinterlands"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Hinterlands’ Wildhammer dwarves forged new ties with the Highvale elves, provoking hostile attention from the Revantusk.",["title"]="Wildhammer Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7842:description:1-81","7842:description:83-143","7842:description:145-173","7842:description:178-250","7842:description:252-287","7842:objective:1-148","7842:objective:150-190","7842:objective:195-256"},["minimumStage"]=2,["questID"]=7842,["sourceHash"]="68136594cbe3ebec85eaad3ae46b67a72a302278b2ca0b217fb32178fc337f00"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-wildhammer-clan",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The trolls regarded the bond between Wildhammer and gryphon as close enough to exploit by attacking the birds and taking their feathers.",["title"]="Wildhammer Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7843:description:1-83","7843:description:88-106","7843:description:108-168","7843:description:170-182","7843:description:184-214","7843:description:216-259","7843:description:261-287","7843:description:289-318","7843:objective:1-208","7843:objective:210-250","7843:objective:255-324"},["minimumStage"]=2,["questID"]=7843,["sourceHash"]="8f4600ff36c31f4e22c79e3600aef80f7b4e821dc06b962bd4e551a8b7de98b5"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-wildhammer-clan",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Aerie Peak was their settlement in the western Hinterlands, with a well at its center.",["title"]="Wildhammer Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7843:description:1-83","7843:description:88-106","7843:description:108-168","7843:description:170-182","7843:description:184-214","7843:description:216-259","7843:description:261-287","7843:description:289-318","7843:objective:1-208","7843:objective:210-250","7843:objective:255-324","7843:completion:1-63","7843:completion:65-95","7843:completion:97-109","7843:completion:114-131","7843:completion:133-142","7843:completion:144-177"},["minimumStage"]=4,["questID"]=7843,["sourceHash"]="8f4600ff36c31f4e22c79e3600aef80f7b4e821dc06b962bd4e551a8b7de98b5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-wildhammer-clan",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Otho’s feather-wrapped, bloodied spear was planted by Aerie Peak’s well as a threat. His later questions did not establish that the dwarves abandoned their home.",["title"]="Wildhammer Clan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5128:description:1-198","5128:description:203-342","5128:description:347-449","5128:description:454-474","5128:objective:1-68"},["minimumStage"]=2,["questID"]=5128,["sourceHash"]="d6d5949820c520cc9d7c1b543b1720990b30e9b985bb29a4eded2986aaaa67e8"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-emerald-circle",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-felwood"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Emerald Circle’s druids worked in Felwood to heal the land’s corruption.",["title"]="Emerald Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5128:description:1-198","5128:description:203-342","5128:description:347-449","5128:description:454-474","5128:objective:1-68"},["minimumStage"]=2,["questID"]=5128,["sourceHash"]="d6d5949820c520cc9d7c1b543b1720990b30e9b985bb29a4eded2986aaaa67e8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-emerald-circle",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Kelek Skykeeper’s experience with Felwood’s furbolgs made him a proposed interpreter of the Winterfall high chief’s log and the mystery of firewater.",["title"]="Emerald Circle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3385:description:1-131","3385:description:136-153","3385:description:155-218","3385:description:220-326","3385:description:331-389","3385:description:391-435","3385:description:437-489","3385:description:494-509","3385:objective:1-45","3385:objective:47-116"},["minimumStage"]=2,["questID"]=3385,["sourceHash"]="06de3c71d67392e59b5d6590d9ff204a0209eafa16ba6ca87952ba5f66709a25"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-undermarket",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-searing-gorge"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Undermarket was a trading operation described by its opponents as willing to sell, move or exchange almost anything for the right payment.",["title"]="Undermarket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3385:description:1-131","3385:description:136-153","3385:description:155-218","3385:description:220-326","3385:description:331-389","3385:description:391-435","3385:description:437-489","3385:description:494-509","3385:objective:1-45","3385:objective:47-116"},["minimumStage"]=2,["questID"]=3385,["sourceHash"]="06de3c71d67392e59b5d6590d9ff204a0209eafa16ba6ca87952ba5f66709a25"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-undermarket",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Its Searing Gorge base operated in the Cauldron under Trade Master Kovic.",["title"]="Undermarket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3385:description:1-131","3385:description:136-153","3385:description:155-218","3385:description:220-326","3385:description:331-389","3385:description:391-435","3385:description:437-489","3385:description:494-509","3385:objective:1-45","3385:objective:47-116"},["minimumStage"]=2,["questID"]=3385,["sourceHash"]="06de3c71d67392e59b5d6590d9ff204a0209eafa16ba6ca87952ba5f66709a25"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-undermarket",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Kovic’s ties to the Dark Iron dwarves and the service of his minion Clunk placed the operation within the region’s struggle over trade and power.",["title"]="Undermarket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3062:description:1-93","3062:description:95-158","3062:description:160-235","3062:description:237-289","3062:description:294-431","3062:description:436-506","3062:objective:1-66"},["minimumStage"]=2,["questID"]=3062,["sourceHash"]="dcf950b5bd5c2ae42499421830a440f922d558a500c732b41fe11819d81cf050"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="faction-northspring",["kind"]="faction",["newSubject"]=true,["related"]={"feralas"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Northspring were the harpies ruled by Edana Hatetalon in Feralas.",["title"]="Northspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3062:description:1-93","3062:description:95-158","3062:description:160-235","3062:description:237-289","3062:description:294-431","3062:description:436-506","3062:objective:1-66"},["minimumStage"]=2,["questID"]=3062,["sourceHash"]="dcf950b5bd5c2ae42499421830a440f922d558a500c732b41fe11819d81cf050"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-northspring",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="A horn carried by the harpies could call their queen to the Hatetalon stones in the northern part of their ruins.",["title"]="Northspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"518:description:1-68","518:description:70-168","518:description:173-211","518:description:216-226","518:description:228-232","518:description:234-240","518:objective:1-55"},["minimumStage"]=2,["questID"]=518,["sourceHash"]="1234e6ccb8217784697cd3d83d2d4197eb7a19d5ee7c3e681500e13360ca5481"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="faction-crushridge",["kind"]="faction",["newSubject"]=true,["related"]={"atlas-place-alterac-mountains"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Mug’thol’s Crushridge ogres occupied the ruins of Alterac, where Melisara sought to weaken their numbers before attacking their leader.",["title"]="Crushridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"519:description:1-55","519:description:57-129","519:description:134-233","519:objective:1-82"},["minimumStage"]=2,["questID"]=519,["sourceHash"]="981f7e99e5b3f91fc38040921fc7c2b7c90eccab92612c23e010121fc4443d36"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="faction-crushridge",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Targ, Muckrake and Glommus served as Mug’thol’s loyal lieutenants and became the next targets of Melisara’s campaign.",["title"]="Crushridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["minimumStage"]=2,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-crushridge",["kind"]="faction",["newSubject"]=false,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="Mug’thol’s use of the Crown of Will broke the possession that had bound him to Sylvanas, provoking the campaign against him and his warband.",["title"]="Crushridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7736:description:1-64","7736:description:66-132","7736:description:135-180","7736:description:185-206","7736:description:209-222","7736:description:225-232","7736:description:237-269","7736:description:272-339","7736:objective:1-82"},["minimumStage"]=2,["questID"]=7736,["sourceHash"]="e80b1b85ea4d03f82ba20e2260e5dc1c7eca02e8f1ee894db7a744908c52d49f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="faction-thorium-brotherhood",["kind"]="faction",["newSubject"]=true,["related"]={},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="The Brotherhood’s fiery flux supplies depended on incendosaur scales, coal and kingsblood brought in by outside helpers.",["title"]="Thorium Brotherhood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7701:description:1-235","7701:description:240-305","7701:objective:1-134","7701:objective:139-180","7701:objective:182-270"},["minimumStage"]=2,["questID"]=7701,["sourceHash"]="592a4264c73912703707ac7af30d8541e2701f39fe68f95f2dd7fd20052e6891"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="faction-thorium-brotherhood",["kind"]="faction",["newSubject"]=false,["related"]={"atlas-place-searing-gorge"},["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="faction-source-context-2026-10-26-r1",["text"]="An order from Overseer Oilfist named Maltorius a rogue Brotherhood agent now commanding the Dark Iron Slag Pit crew and placed a bounty on his head.",["title"]="Thorium Brotherhood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8182:description:1-30","8182:description:33-147","8182:description:150-230","8182:description:235-321","8182:description:324-420","8182:description:423-495",